(function(){
  const q=document.getElementById('q'), st=document.getElementById('statusSel');
  const apply=()=>{const u=new URL(location.href);u.searchParams.delete('page');q.value?u.searchParams.set('q',q.value):u.searchParams.delete('q');st.value?u.searchParams.set('status',st.value):u.searchParams.delete('status');location.href=u.toString();};
  q.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();apply();}});
  st.addEventListener('change',apply);
  const rows=[...document.querySelectorAll('tbody tr[data-name]')];
  q.addEventListener('input',()=>{const v=q.value.toLowerCase();rows.forEach(r=>r.style.display=r.dataset.name.includes(v)?'':'none');});
})();
</script></body></html>